{
  "type": "object",
  "properties": {
    "exactitud_factual": { "type": "integer", "minimum": 1, "maximum": 5, "description": "Exactitud factual de la respuesta respecto del contexto (1 a 5)" },
    "estado_veredicto": { "type": "string", "enum": ["ACEPTADO", "CORREGIR", "RECHAZADO"] },
    "categoria_error": { "type": "string", "enum": ["ninguno", "dato_inventado", "dato_incompleto", "sin_cita_de_fuente", "fuera_de_politica", "no_aplico_regla_no_se", "no_se_indebido", "tono_o_formato"] },
    "critica": { "type": "string", "description": "Critica accionable para el reintento" }
  },
  "required": ["exactitud_factual", "estado_veredicto", "categoria_error", "critica"],
  "additionalProperties": false
}

parameters.jsCode:
const UMBRAL_EXACTITUD = 4;
const MAX_INTENTOS = 2;
const PRECIOS = { 'gpt-4o': [2.5, 10], 'gpt-4o-mini': [0.15, 0.6] };
const entrada = $('Payload JSON para el Juez').first().json;
const modeloJuez = entrada.modelo_juez || 'gpt-4o';
const r = $input.first().json;
function textoJuez(x) {
  const outs = Array.isArray(x.output) ? x.output : [];
  for (const o of outs) for (const c of (o.content || [])) if (c.text !== undefined) return c.text;
  if (x.output_text !== undefined) return x.output_text;
  if (x.text !== undefined) return x.text;
  if (x.exactitud_factual !== undefined) return x;
  return JSON.stringify(x);
}
const raw = textoJuez(r);
let v = raw;
if (typeof v === 'string') {
  const limpio = v.replace(/```json/gi, '').replace(/```/g, '');
  const m = limpio.match(/\{[\s\S]*\}/);
  try { v = JSON.parse(m ? m[0] : limpio); } catch (e) { v = null; }
}
if (v && typeof v === 'object') {
  v.exactitud_factual = parseInt(v.exactitud_factual, 10);
  v.estado_veredicto = String(v.estado_veredicto || '').trim().toUpperCase();
}
const valido = !!v && Number.isInteger(v.exactitud_factual) && ['ACEPTADO', 'CORREGIR', 'RECHAZADO'].includes(v.estado_veredicto);
const veredicto = valido
  ? { exactitud_factual: v.exactitud_factual, estado_veredicto: v.estado_veredicto, categoria_error: v.categoria_error || 'ninguno', critica: v.critica || '' }
  : { exactitud_factual: 1, estado_veredicto: 'RECHAZADO', categoria_error: 'tono_o_formato', critica: 'El supervisor no devolvio un JSON valido; se congela la autonomia y se deriva a revision humana.' };
let decision;
if (veredicto.estado_veredicto === 'ACEPTADO' && veredicto.exactitud_factual >= UMBRAL_EXACTITUD) decision = 'ACEPTAR';
else if (veredicto.estado_veredicto !== 'RECHAZADO' && (entrada.intento || 1) < MAX_INTENTOS) decision = 'CORREGIR';
else decision = 'ESCALAR';
const tin = (r.usage && r.usage.input_tokens) || 0;
const tout = (r.usage && r.usage.output_tokens) || 0;
const p = PRECIOS[modeloJuez] || PRECIOS['gpt-4o'];
const { payload_juez, ...resto } = entrada;
return [{ json: { ...resto,
  veredicto, veredicto_json: JSON.stringify(veredicto), veredicto_valido: valido, decision,
  umbral_exactitud: UMBRAL_EXACTITUD, modelo_juez: modeloJuez, tokens_juez_in: tin, tokens_juez_out: tout,
  costo_juez_usd: (tin * p[0] + tout * p[1]) / 1e6, prompt_version_juez: 'supervisor-qa@pf-1.0'
} }];
